+     */
+    public LayerManager copy() {
+        LayerManager newMgr = new LayerManager(filterSupplier, extendCheck, filterCleanup, false);
+        for (BloomFilter bf : filters) {
+            newMgr.filters.add(bf.copy());
+        }
+        return newMgr;
+    }
