        Shape shape = new Shape(3, 100, 0.01);
        ArrayCountingBloomFilter filter = createEmptyFilter(shape);

        LongPredicate consumer = value -> value == 0;

        assertTrue(filter.forEachBitMap(consumer));
    }
}

