    public ArrayCountingBloomFilter copy() {
        return new ArrayCountingBloomFilter(this);
    }

    @Override
    public boolean isSparse() {
        return true;
    }

    @Override
    public int cardinality() {
        return (int) IntStream.range(0, counts.length).filter(i -> counts[i] > 0).count();
    }

