+     *
+     * @return the probability of collision.
+     */
+    public final double getProbability() {
+        // (1 - exp(-kn/m))^k
+        double p = Math.pow(1.0 - Math.exp(-1.0 * numberOfHashFunctions * numberOfItems / numberOfBits),
+            numberOfHashFunctions);
