        uniqueList.add(1);
        uniqueList.add(2);
        uniqueList.add(3);

        // Define a predicate that does not match any elements
        Predicate<Integer> greaterThanThree = num -> num > 3;

        // Apply removeIf with the predicate
        boolean result = uniqueList.removeIf(greaterThanThree);

